import json

data = json.load(open('/root/schema-dag-extraction/results/exp1_text_match_reeval.json'))
for ck in ['count_22', 'count_44']:
    for i in range(5):
        k = f'{ck}_random_{i}'
        if k not in data:
            break
        d = data[k]
        m = d.get('metrics', {})
        print(f'{k}: metrics keys = {sorted(m.keys())}')
        for mk in ['recall', 'text_match_recall', 'entity_recall']:
            if mk in m:
                print(f'  {mk} = {m[mk]}')
        if 'per_type' in d:
            pt = d['per_type']
            if isinstance(pt, dict):
                # Try to compute aggregate recall from per_type
                total_tp = sum(v.get('tp', 0) for v in pt.values())
                total_gold = sum(v.get('gold', v.get('total_gold', 0)) for v in pt.values())
                if total_gold > 0:
                    print(f'  per_type aggregate: tp={total_tp}, gold={total_gold}, recall={total_tp/total_gold:.4f}')
                # Show first type's keys
                first_type = next(iter(pt.values()))
                print(f'  per_type value keys: {sorted(first_type.keys())}')
"
